import { getProgramName } from './lib/cli/programName.mjs';
import { parseArguments } from './lib/cli/parseArguments.mjs';
import { replaceLiteral } from './lib/runtime/text.mjs';
import {
  DATASET_EXECUTABLE_NAME,
  runExecutable,
} from './lib/yaml/runExecutable.mjs';

const programName = getProgramName(process.argv);
const parsed = parseArguments(process.argv.slice(2));

if (parsed.kind === 'run') {
  const result = runExecutable(['--a', parsed.value]);
  writeResult(result.stdout, result.stderr);
  process.exit(result.status);
}

const forwarded = runExecutable(parsed.forwardArgs);

if (parsed.kind === 'help') {
  const rewrittenHelp = replaceLiteral(
    forwarded.stdout,
    DATASET_EXECUTABLE_NAME,
    programName,
  );
  writeResult(rewrittenHelp, forwarded.stderr);
  process.exit(forwarded.status);
}

const rewrittenError = replaceLiteral(
  forwarded.stderr,
  DATASET_EXECUTABLE_NAME,
  programName,
);

writeResult(forwarded.stdout, rewrittenError);
process.exit(forwarded.status);

function writeResult(stdout, stderr) {
  if (stdout !== '') {
    process.stdout.write(stdout);
  }

  if (stderr !== '') {
    process.stderr.write(stderr);
  }
}

export function parseArguments(args) {
  const forwardArgs = args.slice();
  let latestAValue;
  let sawRecognizedAssignment = false;

  for (let index = 0; index < args.length; index += 1) {
    const token = args[index];

    if (token === '--a') {
      sawRecognizedAssignment = true;

      const nextToken = args[index + 1];

      if (nextToken === undefined || !isConfidentValueToken(nextToken)) {
        return {
          kind: 'passthrough',
          forwardArgs,
        };
      }

      latestAValue = nextToken;
      index += 1;
      continue;
    }

    if (startsWithALongAssignment(token)) {
      sawRecognizedAssignment = true;
      latestAValue = token.slice(4);
      continue;
    }

    if (isHelpToken(token)) {
      return {
        kind: 'help',
        forwardArgs,
      };
    }

    return {
      kind: 'passthrough',
      forwardArgs,
    };
  }

  if (!sawRecognizedAssignment) {
    return {
      kind: 'passthrough',
      forwardArgs,
    };
  }

  return {
    kind: 'run',
    value: latestAValue,
  };
}

function startsWithALongAssignment(token) {
  return token.length >= 4 && token.slice(0, 4) === '--a=';
}

function isHelpToken(token) {
  return isLongHelpToken(token) || isShortHelpToken(token);
}

function isLongHelpToken(token) {
  if (token.length <= 2) {
    return false;
  }

  if (token[0] !== '-' || token[1] !== '-') {
    return false;
  }

  if (token.indexOf('=') !== -1) {
    return false;
  }

  return '--help'.slice(0, token.length) === token;
}

function isShortHelpToken(token) {
  if (token.length < 2) {
    return false;
  }

  if (token[0] !== '-' || token[1] !== 'h') {
    return false;
  }

  return token.length === 2 || token[2] !== '=';
}

// This recognizer stays conservative on purpose so uncertain CLI shapes fall back
// to the reference executable instead of guessing argparse edge behavior locally.
function isConfidentValueToken(token) {
  if (token.length === 0) {
    return true;
  }

  if (token[0] !== '-') {
    return true;
  }

  if (token === '-') {
    return true;
  }

  const secondCharacter = token[1];

  if (secondCharacter === undefined) {
    return false;
  }

  if (isDigit(secondCharacter) || secondCharacter === '.') {
    return true;
  }

  return isWhitespace(secondCharacter) || secondCharacter === ':';
}

function isDigit(character) {
  return character >= '0' && character <= '9';
}

function isWhitespace(character) {
  return (
    character === ' ' ||
    character === '\t' ||
    character === '\n' ||
    character === '\r' ||
    character === '\f' ||
    character === '\v'
  );
}
